import { forbidden } from 'next/navigation';
import { verifyAdmin } from '../lib/auth';

export default async function AdminPage() {
  const { isAdmin } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome to the protected admin area.</p>
      <div style={{ 
        marginTop: '1rem', 
        padding: '1rem', 
        backgroundColor: '#f0f9ff', 
        border: '1px solid #bae6fd', 
        borderRadius: '0.375rem' 
      }}>
        <p>This content is only visible to administrators.</p>
      </div>
    </div>
  );
}

import Link from 'next/link';

export default function Forbidden() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      fontFamily: 'system-ui, sans-serif',
      textAlign: 'center',
      padding: '1rem'
    }}>
      <h1 style={{ fontSize: '3rem', fontWeight: 'bold', marginBottom: '1rem', color: '#dc2626' }}>403</h1>
      <h2 style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>Access Denied</h2>
      <p style={{ marginBottom: '2rem', color: '#4b5563' }}>
        Sorry, you don't have permission to access this page.
      </p>
      <Link 
        href="/"
        style={{
          padding: '0.75rem 1.5rem',
          backgroundColor: '#2563eb',
          color: 'white',
          textDecoration: 'none',
          borderRadius: '0.375rem',
          fontWeight: 500,
          transition: 'background-color 0.2s'
        }}
      >
        Return Home
      </Link>
    </div>
  );
}

